"use client"

import * as React from "react"
import * as TabsPrimitive from "@radix-ui/react-tabs"

import { useComposedRefs } from "@/lib/0nlytype/refs"
import { cn } from "@/lib/utils"
import { roll } from "@/lib/0nlytype/roll"

type TabsProps = React.ComponentProps<typeof TabsPrimitive.Root> & {
  /**
   * line: a line slides under the word in view, leading edge first.
   * rubato: no line; the chosen word takes width and weight from the others, and the bar keeps its length.
   * open: the words stacked in ruled cells beside the panel; the rule between them opens beside the chosen one.
   * Vertical by default, so Up and Down move.
   */
  variant?: "line" | "rubato" | "open"
}

function Tabs({ className, variant = "line", orientation, dir, ref, ...props }: TabsProps) {
  // Radix writes dir="ltr" on the root unless told otherwise, which would turn a right-to-left page's
  // tabs and arrow keys around. Without a dir, the tabs take the direction of the page around them,
  // read as they mount, before the first paint (as the menus and the toggle group do).
  const [around, setAround] = React.useState<"rtl">()
  const composedRef = useComposedRefs(React.useCallback((node: HTMLDivElement | null) => {
    const up = node?.parentElement
    if (!dir && up && getComputedStyle(up).direction === "rtl") setAround("rtl")
  }, [dir]), ref)
  return (
    <TabsPrimitive.Root
      ref={composedRef}
      dir={dir ?? around}
      data-slot="tabs"
      data-variant={variant}
      orientation={orientation ?? (variant === "open" ? "vertical" : "horizontal")}
      className={cn("db-tabs-root", className)}
      {...props}
    />
  )
}

/**
 * Sets where the line goes: --x (left), --r (right inset) and --y (lift to the
 * last row when the words wrap), measured from the active tab, plus --t and --b
 * (its top and bottom insets) for the open variant's break in the rule. data-dir
 * says which way it moved (left, right, up, down) so the leading edge can go
 * first. Physical measurements, so right-to-left needs nothing more.
 */
function useFollow() {
  const list = React.useRef<HTMLDivElement | null>(null)
  React.useLayoutEffect(() => {
    const el = list.current
    if (!el) return
    let ready = false
    const follow = () => {
      const on = el.querySelector<HTMLElement>('[role="tab"][data-state="active"]')
      if (!on) return
      const b = el.getBoundingClientRect()
      const r = on.getBoundingClientRect()
      const lastRow = Math.max(...[...el.querySelectorAll('[role="tab"]')].map((t) => t.getBoundingClientRect().bottom))
      const k = b.width / el.offsetWidth || 1 // on-screen px per CSS px: a scaled or zoomed ancestor would throw the line off
      const x = (r.left - b.left) / k
      const t = (r.top - b.top) / k
      const was = parseFloat(el.style.getPropertyValue("--x")) || 0
      const wasT = parseFloat(el.style.getPropertyValue("--t")) || 0
      el.dataset.dir = Math.abs(x - was) > 0.5 ? (x > was ? "right" : "left") : t >= wasT ? "down" : "up"
      el.style.setProperty("--x", `${x}px`)
      el.style.setProperty("--t", `${t}px`)
      el.style.setProperty("--b", `${(b.bottom - r.bottom) / k}px`)
      el.style.setProperty("--r", `${(b.right - r.right) / k}px`)
      el.style.setProperty("--y", `${(r.bottom - lastRow) / k}px`)
    }
    follow()
    // Nothing glides until the person has chosen: the first place is just where it starts.
    const chose = new MutationObserver(() => {
      if (!ready) el.setAttribute("data-ready", "")
      ready = true
      follow()
    })
    chose.observe(el, { attributes: true, attributeFilter: ["data-state"], subtree: true })
    const resize = new ResizeObserver(follow)
    resize.observe(el)
    el.querySelectorAll('[role="tab"]').forEach((t) => resize.observe(t))
    document.fonts?.ready.then(follow)
    return () => {
      chose.disconnect()
      resize.disconnect()
    }
  }, [])
  return list
}

/** Words with a hairline beneath; a line slides to the one in view, leading edge first. */
function TabsList({ className, children, ref, ...props }: React.ComponentProps<typeof TabsPrimitive.List>) {
  const follow = useFollow()
  const composedRef = useComposedRefs(follow, ref)
  return (
    <TabsPrimitive.List
      ref={composedRef}
      data-slot="tabs-list"
      className={cn("db-tabs", className)}
      {...props}
    >
      {children}
      <span data-slot="tabs-line" className="db-tabs-line" aria-hidden="true" />
    </TabsPrimitive.List>
  )
}

type TabsTriggerProps = React.ComponentProps<typeof TabsPrimitive.Trigger> & {
  /** How many things are behind this tab, raised beside its name. */
  count?: number | string
}

function TabsTrigger({ className, count, children, ...props }: TabsTriggerProps) {
  return (
    <TabsPrimitive.Trigger data-slot="tabs-trigger" className={className} {...props}>
      {children}
      {count !== undefined ? <sup>{count}</sup> : null}
    </TabsPrimitive.Trigger>
  )
}

/** The count of what's showing, set huge and cropped by the rule it sinks into. Put it inside TabsList; it rolls when the number changes. */
function TabsCount({ children, className, ...props }: Omit<React.ComponentProps<"span">, "children"> & { children: number | string }) {
  const text = String(children)
  const inner = React.useRef<HTMLSpanElement>(null)
  const [shown, setShown] = React.useState(text)
  React.useEffect(() => {
    if (text === shown) return
    const el = inner.current
    if (!el) return setShown(text)
    roll(el, () => setShown(text), "100%", +text > +shown ? 1 : -1)
  }, [text, shown])
  return (
    <span data-slot="tabs-count" aria-hidden="true" className={cn("db-tabs-count", className)} {...props}>
      <span ref={inner}>{shown}</span>
    </span>
  )
}

function TabsContent({ className, ...props }: React.ComponentProps<typeof TabsPrimitive.Content>) {
  return <TabsPrimitive.Content data-slot="tabs-content" className={className} {...props} />
}

export { Tabs, TabsList, TabsTrigger, TabsContent, TabsCount, type TabsProps }

@layer components {
  /* ── db-tabs ── words; a line slides under the one in view.
     Radix keeps the roving focus and the arrow keys; the line reads --x, --r, --y
     from the active tab (see tabs.tsx). */
  .db-tabs {
    position: relative; display: flex; flex-wrap: wrap; column-gap: var(--db-space-6); row-gap: var(--db-space-2);
    padding-block-end: var(--db-space-3);
    background: linear-gradient(var(--db-rule), var(--db-rule)) no-repeat 0 100% / 100% var(--db-hairline);
  }
  .db-tabs > [role="tab"] {
    appearance: none; border: 0; background: none; margin: 0; padding: 0; cursor: pointer;
    font-size: var(--db-mp); line-height: var(--db-mp-lh); color: var(--db-pencil);
    transition: color var(--db-allegro);
  }
  .db-tabs > [role="tab"]:is(:hover, [data-force~="hover"]) { color: var(--db-graphite); }
  .db-tabs > [role="tab"][data-state="active"] { color: var(--db-ink); }
  .db-tabs > [role="tab"]:disabled { cursor: not-allowed; opacity: 0.5; }
  .db-tabs sup { font-size: 0.5em; line-height: 0; vertical-align: 0.95em; margin-inline-start: 0.2em; font-variant-numeric: tabular-nums; color: var(--db-pencil); }
  .db-tabs-line {
    position: absolute; left: var(--x, 0px); right: var(--r, 100%); bottom: 0; height: var(--db-stroke);
    background: var(--db-ink); translate: 0 var(--y, 0px); pointer-events: none;
    transition: left var(--db-andante) var(--db-breath), right var(--db-andante) var(--db-breath), translate var(--db-moderato) var(--db-breath);
  }
  .db-tabs[data-dir="right"] .db-tabs-line { transition-delay: 110ms, 0s, 0s; }
  .db-tabs[data-dir="left"] .db-tabs-line { transition-delay: 0s, 110ms, 0s; }
  .db-tabs:not([data-ready]) .db-tabs-line { transition: none; }
  /* The count of what's showing, set huge and cropped by the rule it sinks into. */
  .db-tabs-count {
    position: absolute; inset-inline-end: 0; inset-block-end: 0; block-size: 0.56em; overflow: clip; pointer-events: none;
    font-size: clamp(5rem, 10vw, 9rem); font-weight: 100; font-stretch: 112%; line-height: 0.78; letter-spacing: -0.04em;
    color: var(--db-ink); font-variant-numeric: tabular-nums lining-nums;
  }
  .db-tabs-count > span { display: block; }
  @media (max-width: 700px) { .db-tabs-count { display: none; } }
  @media (max-width: 40rem) { .db-tabs { column-gap: var(--db-space-4); } } /* four words stay on one line at phone width, so the line has one row to sit under */

  /* rubato: "robbed time". No line: the chosen word takes width and weight from the others (font-stretch 75% to
     125%, weight 300 to 600), and the words are spread to both ends so the bar keeps its length while they give
     and take. Pointing leans a word a little wider, in pencil. Voices without a width axis change weight only. */
  .db-tabs-root[data-variant="rubato"] > .db-tabs { justify-content: space-between; column-gap: var(--db-space-4); max-inline-size: calc(var(--db-mp) * 26); } /* a bar, not the page: the give and take stays in view */
  .db-tabs-root[data-variant="rubato"] > .db-tabs > [role="tab"] {
    font-stretch: 75%; font-weight: 300;
    transition: color var(--db-allegro), font-stretch var(--db-andante) var(--db-breath), font-weight var(--db-andante) var(--db-breath);
  }
  .db-tabs-root[data-variant="rubato"] > .db-tabs > [role="tab"]:is(:hover, [data-force~="hover"]):not([data-state="active"], :disabled) { font-stretch: 90%; font-weight: 350; }
  .db-tabs-root[data-variant="rubato"] > .db-tabs > [role="tab"][data-state="active"] { font-stretch: 125%; font-weight: 600; }
  .db-tabs-root[data-variant="rubato"] > .db-tabs > .db-tabs-line { display: none; }

  /* open: the words stacked large like a headline beside the panel, one hairline standing between the two
     columns ("Less is more."). The hairline breaks beside the chosen word, so the word opens onto its panel:
     the choice is marked by a missing line. The break moves like the line, leading edge first. Vertical: Up and Down move. */
  .db-tabs-root[data-variant="open"] { display: grid; grid-template-columns: max-content minmax(0, 1fr); align-items: start; padding-block: var(--db-space-4); }
  .db-tabs-root[data-variant="open"] > .db-tabs { flex-direction: column; flex-wrap: nowrap; gap: 0; padding: 0; background: none; }
  .db-tabs-root[data-variant="open"] > .db-tabs > [role="tab"] {
    text-align: start; padding-block: var(--db-space-2); padding-inline-end: var(--db-space-8);
    font-size: var(--db-mf); line-height: var(--db-mf-lh); letter-spacing: var(--db-mf-tr); font-weight: 300;
    transition: color var(--db-allegro), font-weight var(--db-moderato) var(--db-breath);
  }
  .db-tabs-root[data-variant="open"] > .db-tabs > [role="tab"][data-state="active"] { font-weight: 450; }
  .db-tabs-root[data-variant="open"] > .db-tabs > .db-tabs-line { display: none; }
  .db-tabs-root[data-variant="open"] > .db-tabs::before,
  .db-tabs-root[data-variant="open"] > .db-tabs::after {
    content: ""; position: absolute; inset-inline-end: 0; inline-size: var(--db-hairline); background: var(--db-rule-strong); pointer-events: none;
    transition: block-size var(--db-andante) var(--db-breath);
  }
  /* The hairline overhangs the stack at both ends, so the first or last word breaks it too, not just ends it. */
  .db-tabs-root[data-variant="open"] > .db-tabs::before { inset-block-start: calc(-1 * var(--db-space-4)); block-size: calc(var(--t, 100%) + var(--db-space-4)); }
  .db-tabs-root[data-variant="open"] > .db-tabs::after { inset-block-end: calc(-1 * var(--db-space-4)); block-size: calc(var(--b, 0px) + var(--db-space-4)); }
  .db-tabs-root[data-variant="open"] > .db-tabs[data-dir="down"]::before { transition-delay: 110ms; }
  .db-tabs-root[data-variant="open"] > .db-tabs[data-dir="up"]::after { transition-delay: 110ms; }
  .db-tabs-root[data-variant="open"] > .db-tabs:not([data-ready])::before,
  .db-tabs-root[data-variant="open"] > .db-tabs:not([data-ready])::after { transition: none; }
  .db-tabs-root[data-variant="open"] > [role="tabpanel"] { grid-column: 2; grid-row: 1; min-inline-size: 0; padding-inline-start: var(--db-space-6); padding-block-start: var(--db-space-2); }
  @media (max-width: 40rem) {
    .db-tabs-root[data-variant="open"] > .db-tabs > [role="tab"] { font-size: var(--db-mp); line-height: var(--db-mp-lh); letter-spacing: var(--db-mp-tr); padding-inline-end: var(--db-space-5); }
    .db-tabs-root[data-variant="open"] > [role="tabpanel"] { padding-inline-start: var(--db-space-4); }
  }
  @media (forced-colors: active) {
    .db-tabs-line, .db-tabs-root[data-variant="open"] > .db-tabs::before, .db-tabs-root[data-variant="open"] > .db-tabs::after { forced-color-adjust: none; background: CanvasText; }
    .db-tabs > [role="tab"][data-state="active"] { color: Highlight; }
  }
}
